/**
 * 边上会接光的小按钮（RimLight）
 *
 * 按钮圈着一道细边，光从某一侧打上去，那道亮光贴着边走到指针那边；指针走近
 * 就亮、走远就暗，走过来的时候光还会跟着指针的方向转。
 *
 * 跟原来那套的分别：它是在 <canvas> 里跑一个片元着色器，逐像素算圆角矩形的
 * 有向距离场，再把高光画在边上；这里是拿一张 SVG 画的 —— 一个描边的圆角矩形
 * 当底圈的暗边，另一个同样形状的描边盖上去，描边色是一个线性的光带渐变，
 * 转这个渐变就等于光绕着一圈走。于是：
 *   · 不占 WebGL 上下文、不吃显卡（原来每个按钮一个上下文）；
 *   · 光带的宽窄是「边上多少度」算出来的：span 是实心的那段，softness 是往外
 *     化开的那段，都按最短边折算成像素，写在渐变的两个停点上；
 *   · 每帧只写一处：渐变的 gradientTransform（一个属性），亮度交给 CSS 变量；
 *   · 没人指使的时候光不动（跟原来一样，亮起来要有指针走近），除非 sweep。
 *
 * 减少动效：不自己转、不算平滑，光还是跟着指针指（跟手不是动画）。
 */
import {
  useEffect,
  useId,
  useRef,
  useState,
  type ButtonHTMLAttributes,
  type CSSProperties,
  type ReactNode,
} from "react";
import { cn } from "../../lib/cn";
import "./rim-light.css";

export type RimLightSize = "sm" | "md" | "lg";

export interface RimLightProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  /** 大小：padding 与字号一档一档来。 */
  size?: RimLightSize;
  /** 圆角。 */
  radius?: number;
  /** 按钮底色，tintOpacity 是它的不透明度（0 = 全透）。 */
  tint?: string;
  tintOpacity?: number;
  /** 底下的模糊：大于 0 才开 backdrop-filter。 */
  blur?: number;
  /** 字色。 */
  ink?: string;
  /** 亮光的颜色。 */
  beam?: string;
  /** 底圈那道暗边的颜色。 */
  edge?: string;
  /** 亮光最亮到几分。 */
  intensity?: number;
  /** 实心那段光占边上多少度。 */
  span?: number;
  /** 光往两边化开多少度。 */
  softness?: number;
  /** 边圈的粗细（px）。 */
  thickness?: number;
  /** 指针离到多少像素以内开始亮。 */
  proximity?: number;
  /** 没人管的时候自己慢慢转。 */
  sweep?: boolean;
  children?: ReactNode;
}

/** 没有指针时那道光的朝向。 */
const REST_ANGLE = 132;
/** sweep 时一圈转多久（秒）。 */
const SWEEP_SECONDS = 18;
/** 光跟得多快、亮得多快（每秒的逼近比例）。 */
const TURN = 7;
const RISE = 9;

export function RimLight({
  size = "lg",
  radius = 18,
  tint = "#ffffff",
  tintOpacity = 0,
  blur = 0,
  ink = "#f5f5f5",
  beam = "#ffffff",
  edge = "#525252",
  intensity = 1,
  span = 26,
  softness = 64,
  thickness = 1,
  proximity = 250,
  sweep = false,
  disabled = false,
  className,
  children,
  ...rest
}: RimLightProps) {
  const gradientId = useId();
  const hostRef = useRef<HTMLButtonElement>(null);
  const gradientRef = useRef<SVGLinearGradientElement>(null);
  const [box, setBox] = useState({ w: 0, h: 0 });

  /* 循环里要读最新的值，又不该为它们重开循环。 */
  const boxRef = useRef(box);
  boxRef.current = box;
  const tuneRef = useRef({ intensity, span, softness, proximity, sweep });
  tuneRef.current = { intensity, span, softness, proximity, sweep };

  const inset = Math.max(thickness, 0.5) / 2;
  const w = box.w;
  const h = box.h;
  const corner = Math.max(0, Math.min(radius, Math.min(w, h) / 2) - inset);
  const short = Math.max(Math.min(w, h) / 2, 1);
  /** 渐变轴要够长，转到哪个角度都跨得过整圈 —— 以一个圆心为准，两头各一半。 */
  const axis = Math.max(Math.hypot(w, h) * 2, 1);
  const toRad = Math.PI / 180;
  /* 光带的两个停点：中间实心 span 度，往外 softness 度化开。 */
  const core = (short * Math.sin((span / 2) * toRad)) / axis;
  const fade = (short * Math.sin((softness / 2) * toRad)) / axis;

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return undefined;
    const measure = () => {
      const rect = host.getBoundingClientRect();
      setBox((current) =>
        Math.abs(current.w - rect.width) < 0.5 && Math.abs(current.h - rect.height) < 0.5
          ? current
          : { w: rect.width, h: rect.height },
      );
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(host);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    const host = hostRef.current;
    const gradient = gradientRef.current;
    if (!host || !gradient) return undefined;
    const calm = window.matchMedia("(prefers-reduced-motion: reduce)");

    let raf = 0;
    /* 第一帧不比 —— rAF 给的时刻是这一帧的「开始」，可能比 effect 里此刻还早。 */
    let last = 0;
    let angle = REST_ANGLE;
    let lit = 0;
    let wroteAngle = Number.NaN;
    let wroteLit = -1;
    let sweepPhase = 0;
    let lastBox = "";
    /** 指针最后落在哪儿、离多远、算出来的光朝哪边。 */
    let at: { x: number; y: number } | null = null;
    let fresh = false;
    let aim = REST_ANGLE;
    let near = 0;

    const onMove = (event: PointerEvent) => {
      /* 手指没有「走近」这一说。 */
      if (event.pointerType === "touch") return;
      at = { x: event.clientX, y: event.clientY };
      fresh = true;
    };
    window.addEventListener("pointermove", onMove, { passive: true });

    const tick = (now: number) => {
      raf = window.requestAnimationFrame(tick);
      const dt = last ? Math.min(Math.max((now - last) / 1000, 0), 0.05) : 0;
      last = now;
      const tune = tuneRef.current;
      const { w: bw, h: bh } = boxRef.current;
      const still = calm.matches;

      /* 指针动过：离得多近、光朝哪边。 */
      if (fresh && at && bw > 0) {
        fresh = false;
        const rect = host.getBoundingClientRect();
        const outX = Math.max(rect.left - at.x, 0, at.x - rect.right);
        const outY = Math.max(rect.top - at.y, 0, at.y - rect.bottom);
        const dist = Math.hypot(outX, outY);
        const reach = Math.max(tune.proximity, 1);
        const t = still ? (dist === 0 ? 1 : 0) : Math.max(0, 1 - dist / reach);
        near = t * t * (3 - 2 * t);
        aim = (Math.atan2(at.y - (rect.top + bh / 2), at.x - (rect.left + bw / 2)) * 180) / Math.PI;
      }

      /* 谁说了算：指针在近处就听指针的，否则自己转（sweep），都没有就暗着。
         停用的按钮亮起来只会让人以为能点，干脆不跟着亮。 */
      const usable = !host.disabled;
      let wantAngle = aim;
      let wantLit = usable ? near : 0;
      if (usable && near === 0 && tune.sweep && !still) {
        sweepPhase = (sweepPhase + (360 / SWEEP_SECONDS) * dt) % 360;
        wantAngle = REST_ANGLE + sweepPhase;
        wantLit = 1;
      }

      const step = (rate: number) => (still ? 1 : 1 - Math.exp(-dt * rate));
      const turn = ((wantAngle - angle + 540) % 360) - 180;
      /* 转过来就归一到一圈之内：光多绕几圈是同一个朝向，那个数没必要越攒越大。 */
      angle = (((angle + turn * step(TURN)) % 360) + 360) % 360;
      lit = Math.min(Math.max(lit + (wantLit - lit) * step(RISE), 0), 1);

      /* 尺寸换了，React 会按新几何把这些属性重写一遍 —— 我们这边也重写，
         免得那道「没变就不写」的省事规矩把旧的那一下留住。 */
      const stamp = `${bw}x${bh}`;
      if (stamp !== lastBox) {
        lastBox = stamp;
        wroteAngle = Number.NaN;
      }

      if (Math.abs(angle - wroteAngle) > 0.05 || Number.isNaN(wroteAngle)) {
        wroteAngle = angle;
        /* 渐变轴是横着的、光带竖在中间，所以轴要比「光朝哪边」少转 90 度：
           轴 0 度时亮的是上下两个点，-90 度时亮的才是左右两个点。 */
        gradient.setAttribute(
          "gradientTransform",
          `rotate(${(angle - 90).toFixed(2)} ${(bw / 2).toFixed(2)} ${(bh / 2).toFixed(2)})`,
        );
      }
      if (Math.abs(lit - wroteLit) > 0.002) {
        wroteLit = lit;
        host.style.setProperty("--rl-lit", lit.toFixed(3));
      }
    };
    raf = window.requestAnimationFrame(tick);

    return () => {
      window.cancelAnimationFrame(raf);
      window.removeEventListener("pointermove", onMove);
    };
  }, []);

  return (
    <button
      {...rest}
      ref={hostRef}
      type={rest.type ?? "button"}
      disabled={disabled}
      className={cn("rim-light", `rim-light--${size}`, className)}
      style={
        {
          "--rl-radius": `${radius}px`,
          "--rl-tint": tint,
          "--rl-tint-opacity": tintOpacity,
          "--rl-blur": `${blur}px`,
          "--rl-ink": ink,
          "--rl-beam": beam,
          "--rl-edge": edge,
          "--rl-intensity": intensity,
        } as CSSProperties
      }
    >
      <span className="rim-light__glow" aria-hidden="true" />
      <span className="rim-light__edge" aria-hidden="true">
        {/* 摆在那儿等量的：量到尺寸之前先按 0 画（看不见），但节点一直在 ——
            按帧那个循环是挂在渐变节点上的，节点晚一帧出现，循环就起不来了。 */}
        <svg width="100%" height="100%" viewBox={`0 0 ${w} ${h}`} aria-hidden="true">
          <defs>
            <linearGradient
              id={gradientId}
              ref={gradientRef}
              gradientUnits="userSpaceOnUse"
              x1={w / 2 - axis / 2}
              y1={h / 2}
              x2={w / 2 + axis / 2}
              y2={h / 2}
              gradientTransform={`rotate(${REST_ANGLE - 90} ${w / 2} ${h / 2})`}
            >
              <stop offset={Math.max(0.5 - fade, 0)} stopColor={beam} stopOpacity={0} />
              <stop offset={Math.max(0.5 - core, 0)} stopColor={beam} stopOpacity={1} />
              <stop offset={Math.min(0.5 + core, 1)} stopColor={beam} stopOpacity={1} />
              <stop offset={Math.min(0.5 + fade, 1)} stopColor={beam} stopOpacity={0} />
            </linearGradient>
          </defs>
          <rect
            x={inset}
            y={inset}
            width={Math.max(w - inset * 2, 0)}
            height={Math.max(h - inset * 2, 0)}
            rx={corner}
            fill="none"
            stroke={edge}
            strokeWidth={thickness}
          />
          <rect
            x={inset}
            y={inset}
            width={Math.max(w - inset * 2, 0)}
            height={Math.max(h - inset * 2, 0)}
            rx={corner}
            fill="none"
            stroke={`url(#${gradientId})`}
            strokeWidth={thickness}
          />
        </svg>
      </span>
      <span className="rim-light__label">{children}</span>
    </button>
  );
}

export default RimLight;
